head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
    if (typeof id !== 'string') return id;
    var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
    if (!W.strictMode) id = id.replace(/mf_/g, '');
    if (C[U[id]]) return C[U[id]];
    var r; try { r = F(id); } catch (e) {}
    if (r == undefined && W.strictMode) {
        var P = W.strictModeFrame.id + '_';
        var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
        s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
        if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
    }
    return r == undefined ? id : r;
};
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
    var j = $(q); if (j.length) return j;
    var P = 'mf_', t = q.trim(), r = t.slice(1);
    if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
    return $(t.slice(0, 1) + r);
};
scwin.enableDate = function() {
    var date_enabled = ["20170608", "20170621", "20170629", "20170713", "20170721"]; // 활성화시킬 날짜 지정
    ((j) => j.length ? j : $('.mf_w2calendar_col_date'))($('.w2calendar_col_date')).addClass("date_diabled");
    var cur_date = ((j) => j.length ? j : $('.mf_w2calendar_footer_date'))($('.w2calendar_footer_date'))[0].innerHTML.split("-");
    var cur_year = cur_date[0];
    var cur_month = cur_date[1];
    for (var ix in date_enabled) {
        var date = date_enabled[ix];
        var year = date.substr(0, 4);
        var month = date.substr(4, 2);
        var day = date.substr(6, 2);
        if (cur_year == year && cur_month == month) {
            scwin.__getJq(".w2calendar_date_" + Number(day)).removeClass("date_diabled");
        }
    }
}
scwin.setVal_year = function() {
    debugger;
    var k = 0;
    for (var k; k < scwin.__getDom($p.id + 'inputCal1_calendar_selectbox_year').length; k++) {
        if (scwin.__getDom($p.id + 'inputCal1_calendar_selectbox_year')[k].selected == true) {
            //alert(k)
            break;
        }
    }
    for (var i = 0; i < scwin.__getDom($p.id + 'inputCal1_calendar_selectbox_year').length; i++) {
        //inputCal1_calendar_last_year.click();
        if (scwin.__getDom($p.id + 'inputCal1_calendar_selectbox_year')[k--].innerText == "2018년")
            return;
        scwin.__getObj($p.id+'inputCal1_calendar_last_year').click();
    }
}
scwin.setVal_mon = function() {
    var k = 11;
    for (var i = 0; i < scwin.__getDom($p.id + 'inputCal1_calendar_selectbox_month').length; i++) {
        //inputCal1_calendar_last_year.click();
        if (scwin.__getDom($p.id + 'inputCal1_calendar_selectbox_month')[k--].innerText == "4월")
            return;
        document.getElementsByClassName('w2calendar_header_last_month')[0].click()
    }
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
}
